const fs=require('fs'),path=require('path');const root='outputs/dracula-food';
const changes={
 'collection.description':{ro:'Selecția Dracula-Farm începe cu nucile. Un produs familiar, prezentat cu atenția pentru detaliu care definește Dracula Food.',en:'The Dracula-Farm selection begins with walnuts. A familiar product, presented with the attention to detail that defines Dracula Food.',de:'Die Dracula-Farm Auswahl beginnt mit Walnüssen. Ein vertrautes Produkt, präsentiert mit der Liebe zum Detail, die Dracula Food auszeichnet.'},
 'collection.noresults':{ro:'Niciun produs nu corespunde selecției. Explorează întreaga colecție.',en:'No products match your selection. Explore the full collection.',de:'Keine Produkte entsprechen Ihrer Auswahl. Entdecken Sie die gesamte Kollektion.'}
};
for(const name of ['food/overrides.json','backend/dracula-content.json']){const p=path.join(root,name),data=JSON.parse(fs.readFileSync(p,'utf8'));Object.assign(data.ui,changes);if(name.startsWith('backend/'))data.products=JSON.parse(fs.readFileSync(path.join(root,'food/catalog.json'),'utf8'));fs.writeFileSync(p,JSON.stringify(data,null,2)+'\n');}
// Keep regeneration consistent with the content now supplied.
const builder=path.join(root,'food/build_overrides.py');let source=fs.readFileSync(builder,'utf8');for(const [key,v] of Object.entries(changes)){const line='add('+[key,v.ro,v.en,v.de].map(s=>JSON.stringify(s)).join(', ')+')';source=source.replace(new RegExp("add\\('"+key.replaceAll('.','\\.')+"'[^\\n]*"),line);}fs.writeFileSync(builder,source);
const product='dracula-food-nuci-dracula-farm.png';fs.mkdirSync(path.join(root,'backend/public/assets/produse'),{recursive:true});fs.copyFileSync(path.join(root,'food/assets/produse',product),path.join(root,'backend/public/assets/produse',product));fs.copyFileSync(path.join(root,'food/food.css'),path.join(root,'backend/public/assets/brand/food.css'));
const inventory=path.join(root,'inventar-imagini.csv');let csv=fs.readFileSync(inventory,'utf8');if(!csv.includes(product))csv+='https://chatgpt.com/s/m_6ab691ad087c81919ea2c882178b576d,produs nuci Dracula-Farm,backend/public/assets/produse/'+product+',6e36d39d7406c2751e70f26bdc9ed0135c126ba2d3a2d2301f1bcf7d43cb5fb6,original nemodificat\n';fs.writeFileSync(inventory,csv);
const manifest=path.join(root,'food/build-manifest.json');const m=JSON.parse(fs.readFileSync(manifest,'utf8'));m.products=1;fs.writeFileSync(manifest,JSON.stringify(m,null,2)+'\n');console.log('Food: one walnut product, three translations, original asset, collection copy updated.');
